import{_ as t,a}from"./chunks/project-import.BeRSVcDL.js";import{_ as s,o as n,c as o,a2 as r}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"Project Files & Formats","description":"Everything KomaYomi stores lives in plain files: images in raw/, annotations in data/, generated output in exports/. This page covers the three ways to…","frontmatter":{"description":"Everything KomaYomi stores lives in plain files: images in raw/, annotations in data/, generated output in exports/. This page covers the three ways to…"},"headers":[],"relativePath":"guide/project-files.md","filePath":"guide/project-files.md","lastUpdated":1794780892000}'),i={name:"guide/project-files.md"};function l(d,e,p,h,c,g){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="project-files-formats" tabindex="-1">Project Files &amp; Formats <a class="header-anchor" href="#project-files-formats" aria-label="Permalink to &quot;Project Files &amp; Formats&quot;">​</a></h1><p>Everything KomaYomi stores lives in plain files: images in <code>raw/</code>, annotations in <code>data/</code>, generated output in <code>exports/</code>. This page covers the three ways to move that work elsewhere — and the versioning rules that keep old files readable instead of turning them into archaeology.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Annotations are the expensive part — hours of panel correction, alignment and notes. They must survive a machine change, a dead disk, a study partner, and future app versions. A database backup would be a black box; these formats are plain ZIP and JSON, inspectable with ordinary tools.</p><h2 id="three-portability-layers" tabindex="-1">Three portability layers <a class="header-anchor" href="#three-portability-layers" aria-label="Permalink to &quot;Three portability layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>File</th><th>Contains</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Project package</strong></td><td><code>.mnproj</code></td><td>Images (packaged mode), page JSON, templates, presets, language mapping</td><td>Moving to another machine or archiving a finished volume.</td></tr><tr><td><strong>Exchange files</strong></td><td><code>.mntpl</code>, <code>.mnexp</code>, <code>.mnpage.json</code></td><td>One layout, one export style, or one page</td><td>Sharing a reusable layout or a single annotated page.</td></tr><tr><td><strong>Backup ZIP</strong></td><td><code>.zip</code></td><td>The whole <code>data/</code> folder</td><td>Restoring after a mistake, or keeping a periodic safety copy.</td></tr></tbody></table><figure class="shot"><img src="'+t+`" alt="File menu with open library, project files, recent volumes, save, import and restore entries"><figcaption>The File menu gathers the same actions as the sidebar: save the current page, save as a project, import a project or a page, and restore a backup.</figcaption></figure><h2 id="project-packages-mnproj" tabindex="-1">Project packages (<code>.mnproj</code>) <a class="header-anchor" href="#project-packages-mnproj" aria-label="Permalink to &quot;Project packages (\`.mnproj\`)&quot;">​</a></h2><p>A <code>.mnproj</code> is a ZIP with a text manifest:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>manifest.json</span></span>
<span class="line"><span>pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</span></span>
<span class="line"><span>history/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</span></span>
<span class="line"><span>templates/...</span></span>
<span class="line"><span>presets/...</span></span>
<span class="line"><span>config/library.json          (optional)</span></span>
<span class="line"><span>assets/&lt;sha1&gt;.&lt;ext&gt;          (packaged mode only)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Page version history travels with the project, so reopening it keeps the audit trail described in <a href="/KomaYomi-docs/guide/panels#page-history">Panel Workbench</a>.</p><h3 id="reference-vs-packaged-mode" tabindex="-1">Reference vs packaged mode <a class="header-anchor" href="#reference-vs-packaged-mode" aria-label="Permalink to &quot;Reference vs packaged mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Images</th><th>Size</th><th>Portability</th></tr></thead><tbody><tr><td><strong>Reference</strong></td><td>Only paths and SHA-1 hashes in the manifest.</td><td>Small.</td><td>Needs the original image folder. Supports relinking by hash or filename.</td></tr><tr><td><strong>Packaged</strong></td><td>Deduplicated into <code>assets/&lt;sha1&gt;.&lt;ext&gt;</code>.</td><td>Large.</td><td>Self-contained; importing writes images into <code>raw/</code>.</td></tr></tbody></table><h3 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h3><ol><li>Open <strong>Project file…</strong> in the sidebar, or <strong>File → Save as project…</strong>.</li><li>Choose the mode, a project name and an optional note.</li><li>Click <strong>Create and download .mnproj</strong>.</li></ol><p>The manifest records the app version, creation time, language mapping, an inventory of volumes / chapters / pages and image hashes, and note and annotation counts.</p><h3 id="importing" tabindex="-1">Importing <a class="header-anchor" href="#importing" aria-label="Permalink to &quot;Importing&quot;">​</a></h3><ol><li><strong>Choose a project file…</strong>. The dialog summarises volumes, chapters, pages, notes, annotations, images and templates before writing anything.</li><li>Pick a conflict policy: <strong>Overwrite</strong>, <strong>Merge</strong> or <strong>Skip</strong>. <ul><li><strong>Merge</strong> keeps existing panels and annotations when the incoming page lacks them, and unions notes by id without deleting existing notes.</li></ul></li><li>For a reference-mode project with missing images, optionally choose a <strong>Relink folder</strong> that holds the originals.</li><li>Click <strong>Import</strong>.</li></ol><p>Safety behaviour:</p><ul><li>The current <code>data/</code> is snapshotted to <code>exports/</code> before the import.</li><li>The original project file is backed up under <code>data/backups/projects/</code>.</li><li>Missing images are reported after the import; put them in the relink folder and import again with <strong>Merge</strong> to recover them.</li></ul><h2 id="exchange-files" tabindex="-1">Exchange files <a class="header-anchor" href="#exchange-files" aria-label="Permalink to &quot;Exchange files&quot;">​</a></h2><p><strong>Exchange files…</strong> handles three small formats without touching the whole library.</p><h3 id="mntpl-—-layout-template" tabindex="-1"><code>.mntpl</code> — layout template <a class="header-anchor" href="#mntpl-—-layout-template" aria-label="Permalink to &quot;\`.mntpl\` — layout template&quot;">​</a></h3><p>Exports strip the volume / chapter / page binding, so the template can be imported into another manga and rebound to the current volume, chapter or page. The import dialog lets you bind it and optionally apply it immediately; existing pages are saved first.</p><h3 id="mnexp-—-export-template" tabindex="-1"><code>.mnexp</code> — export template <a class="header-anchor" href="#mnexp-—-export-template" aria-label="Permalink to &quot;\`.mnexp\` — export template&quot;">​</a></h3><p>Stores the layout and style settings for the HTML, Word and print document. Export it now, import it later. Template storage lives in <code>data/templates/export.json</code>.</p><h3 id="mnpage-json-—-one-page" tabindex="-1"><code>.mnpage.json</code> — one page <a class="header-anchor" href="#mnpage-json-—-one-page" aria-label="Permalink to &quot;\`.mnpage.json\` — one page&quot;">​</a></h3><p>A readable page document with panels, notes, tags, groups, annotations and alignment offsets. Older page JSON without the schema envelope can be imported too and is migrated.</p><ul><li><strong>Export current page</strong> writes the current page.</li><li><strong>Choose a page JSON…</strong> then <strong>Overwrite current page</strong> replaces panels, notes and annotations of the selected page.</li><li>Validation failures report the exact field path and never write half-finished data.</li><li>Original files are backed up under <code>data/backups/exchange/</code>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Unsaved changes</p><p>If the page has unsaved edits, exchange exports will not include them and a page import may overwrite them. Save first — the dialog warns, but it is easy to click past.</p></div><h2 id="format-versions" tabindex="-1">Format versions <a class="header-anchor" href="#format-versions" aria-label="Permalink to &quot;Format versions&quot;">​</a></h2><p>Every exchange format carries a schema envelope:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://manga-memo.dev/schemas/page.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;appVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;page&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><table tabindex="0"><thead><tr><th>Kind</th><th>File</th><th>Current version</th></tr></thead><tbody><tr><td><code>mnproj</code></td><td><code>.mnproj</code> manifest</td><td><strong>1</strong></td></tr><tr><td><code>mntpl</code></td><td>layout template</td><td><strong>1</strong></td></tr><tr><td><code>mnexp</code></td><td>export template</td><td><strong>1</strong></td></tr><tr><td><code>page</code></td><td>page document</td><td><strong>1</strong></td></tr><tr><td><code>mntp</code></td><td>panel template (stored)</td><td><strong>1</strong></td></tr><tr><td><code>mnalign</code></td><td>alignment preset (stored)</td><td><strong>1</strong></td></tr><tr><td><code>mnlayout</code></td><td>declarative layout (stored)</td><td><strong>1</strong></td></tr><tr><td><code>mnconfig</code></td><td>library config (stored)</td><td><strong>1</strong></td></tr><tr><td><code>mnstorage</code></td><td>storage config (stored)</td><td><strong>1</strong></td></tr></tbody></table><p>Version rules:</p><ul><li>A file declaring a <strong>higher</strong> version than the app supports is rejected with a clear message: upgrade the app first. The app never guesses at a future format.</li><li>A missing version is treated as <strong>v0</strong> and migrated on import. Early experimental manifests (top-level <code>images</code>, a flat <code>langDirs</code> map) are converted to the current shape.</li><li>Missing optional fields are filled with defaults; invalid images are dropped rather than aborting the whole import.</li><li>On read, page JSON is <strong>normalized</strong>: rectangles are clamped, dangling group references removed, missing ids generated, unknown fields dropped.</li><li>A page JSON that cannot be parsed is treated as absent; the app re-detects and recreates it.</li></ul><h2 id="backup-zip" tabindex="-1">Backup ZIP <a class="header-anchor" href="#backup-zip" aria-label="Permalink to &quot;Backup ZIP&quot;">​</a></h2><p>A backup is a ZIP whose entries are prefixed with <code>data/</code>:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/pages/...</span></span>
<span class="line"><span>data/templates/...</span></span>
<span class="line"><span>data/presets/...</span></span>
<span class="line"><span>data/layouts/...</span></span>
<span class="line"><span>data/library.json</span></span>
<span class="line"><span>data/.backup-meta.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Excluded: <code>data/cache/</code> (thumbnails and remote cache), <code>.tmp</code> files and logs. Restoring overwrites same-named files, keeps pages that are absent from the backup, and writes a snapshot first.</p><h2 id="what-is-not-implemented" tabindex="-1">What is not implemented <a class="header-anchor" href="#what-is-not-implemented" aria-label="Permalink to &quot;What is not implemented&quot;">​</a></h2><ul><li><strong>Vocabulary-list export.</strong> PDF and Word are handled by the <strong>PDF (print)</strong> and <strong>Word document</strong> formats in the export dialog.</li><li><strong>Scheduled backups.</strong> Backups and uploads to a backup target are started manually.</li><li><strong>An in-app image converter or batch renamer.</strong> Prepare files before importing; see <a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a>.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>A reference-mode project shows missing images.</strong> The manifest only stores hashes and paths. Use the relink folder, or export in packaged mode next time.</li><li><strong>“Schema version too new.”</strong> The file came from a newer build. Update the app; do not hand-edit <code>schemaVersion</code>.</li><li><strong>Import overwrote newer notes.</strong> <strong>Overwrite</strong> is destructive by design. Use <strong>Merge</strong> when in doubt; a snapshot was written, but restoring it replaces current data.</li><li><strong>A layout template does not appear.</strong> It is bound to the current chapter/volume filter; check the binding in the import dialog.</li><li><strong>A <code>.mnpage.json</code> import has no images.</strong> Page data never contains images; those come from <code>raw/</code> or a packaged project.</li></ul><figure class="shot"><img src="`+a+'" alt="Project import summary with storage mode, inventory counts, conflict policy, relink folder and the Import button"><figcaption>Project import summary: storage mode, inventory counts, conflict policy, relink folder and the Import button.</figcaption></figure><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>project export form</td><td>Mode, name and note</td></tr><tr><td>exchange files dialog</td><td>Three file types</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/data-format">Data Formats</a> — full JSON field reference.</li><li><a href="/KomaYomi-docs/guide/export">Export</a> — HTML, Word, PDF and PNG output.</li><li><a href="/KomaYomi-docs/guide/remote">Remote Storage &amp; Backup</a> — backup targets.</li></ul>',49)])])}const f=s(i,[["render",l]]);export{b as __pageData,f as default};
